// Bounded receiver corrections C01–C15. All mechanisms below are Source/static
// contracts at revision, not Unit API execution or Live acceptance.
function mechanism(predicate, name, condition, outcome, evidence) {
 for (const r of records.values()) if(predicate(r.fieldPath) && !r.fieldPath.includes('.ephemeralContainers')) {
  r.crossFieldConditions.push(outcome);
  r.evidence.push(...evidence);
  r.cases.push({name, condition, sourceOutcome:outcome});
 }
}
